import {test} from 'node:test';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';
test('配信用Workerのビルド自体で4桁ルームを作成・参加できる',async()=>{execFileSync(process.execPath,['scripts/build.mjs']);const {default:worker}=await import('../dist/server/index.js');let rev=0,map=new Map();const env={BUCKET:{get:async k=>map.has(k)?{etag:String(rev),json:async()=>JSON.parse(map.get(k))}:null,put:async(k,v)=>{map.set(k,v);return {etag:String(++rev)}}}};const request=(path,t,b)=>new Request('https://example.com/api/rooms'+path,{method:b?'POST':'GET',headers:{authorization:'Bearer '+t.repeat(48),'content-type':'application/json'},...(b?{body:JSON.stringify(b)}:{})});let res=await worker.fetch(request('','a',{draft:true}),env);assert.equal(res.status,200);const created=await res.json();res=await worker.fetch(request('/'+created.code+'/join','b',{}),env);const joined=await res.json();assert.equal(res.status,200,JSON.stringify(joined));assert(joined.state.pending);assert.equal(joined.joined,true);});
